The functions \eqref{basis} satisfy 
\begin{equation}  \label{RK}
\begin{split}
\sum_{p=0}^{m}\sum_{q=0}^{m+2\nu }\sum_{j=1}^{d(n,p,q)}\Phi _{m,p,q}^{j}(z) 
\overline{\Phi _{m,p,q}^{j}(w)}&=\frac{(2m+2\nu +n)\Gamma (m+2\nu +n)}{\pi
^{n}\Gamma (m+2\nu +1)}\left( \frac{\left( 1+\langle w,z\rangle \right) ^{2} 
}{(1+|z|^{2})(1+|w|^{2})}\right) ^{\nu } \\
&\times P_{m}^{(n-1,2\nu )}\left( \frac{2|1+\langle z,w\rangle |^{2}}{ 
(1+|z|^{2})(1+|w|^{2})}-1\right) ,
\end{split}
\end{equation}
for every $z,w\in \mathbb{C}^{n}$.

Denoting the sum in the l.h.s of \eqref{RK} by $K_{\nu ,m}(z,w)$
and replacing the orthonormal basis \eqref{basis} of $\mathcal{A}_m^\nu$ by their expressions, we obtain 
\begin{equation}  \label{repr_kern_1}
\begin{split}
K_{\nu ,m}(z,w)&=\left( (1+\left\langle z,z\right\rangle )\left( 1+\left\langle
w,w\right\rangle \right) \right) ^{-\nu -m}\sum_{\substack{ 1\leq j\leq
d(n,p,q)  \\ 0\leq p\leq m,\ 0\leq q\leq m+2\nu }}\left( \gamma
_{p,q}^{n,\nu ,m}\right) ^{2}h_{p,q}^{j}(z,\bar{z})\overline{h_{p,q}^{j}(w, 
\bar{w})} \\
&\times _{2}F{}_{1}\left( 
\begin{array}{c}
p-m,q-m-2\nu \\ 
n+p+q 
\end{array} 
\big|-\left\langle z,z\right\rangle \right) {}_{2}F{}_{1}\left( 
\begin{array}{c}
p-m,q-m-2\nu \\ 
n+p+q 
\end{array} 
\big|-\left\langle w,w\right\rangle \right)
\end{split} 
\end{equation} 
which can also be written as 
\begin{equation}  \label{Kern_2F1}
\begin{split}
K_{\nu ,m}(z,w)& =\left( (1+\left\langle z,z\right\rangle )\left(
1+\left\langle w,w\right\rangle \right) \right) ^{-\nu
-m}\sum_{p=0}^{m}\sum_{q=0}^{m+2\nu }\left( \gamma _{p,q}^{n,\nu ,m}\right)
^{2}\mathfrak{S}_{n;p,q}^{z,w} \\
& \times {}_{2}F{}_{1}\left( 
\begin{array}{c}
p-m,q-m-2\nu \\ 
n+p+q 
\end{array} 
\big|-\left\langle z,z\right\rangle \right) {}_{2}F{}_{1}\left( 
\begin{array}{c}
p-m,q-m-2\nu \\ 
n+p+q 
\end{array} 
\big|-\left\langle w,w\right\rangle \right)
\end{split} 
\end{equation} 
where 
\begin{equation}  \label{sum_hs}
\begin{split}
\mathfrak{S}_{n;p,q}^{z,w}&:=\sum_{\substack{ 1\leq j\leq d(n,p,q)}} 
h_{p,q}^{j}(z,\bar{z})\overline{h_{p,q}^{j}(w,\bar{w})} \\
&=\left( |z||w|\right) ^{p+q}\sum_{\substack{ 1\leq j\leq d(n,p,q)}} 
h_{p,q}^{j}\left( \frac{z}{|z|},\frac{\bar{z}}{|z|}\right) \overline{ 
h_{p,q}^{j}\left( \frac{w}{|w|},\frac{\bar{w}}{|w|}\right) }.
\end{split} 
\end{equation} 
As usual, in the spherical harmonics setting, this last sum can be computed
via the Koornwinder's formula \cite{Koor_1972} as
\begin{equation*}
\mathfrak{S}_{n;p,q}^{z,w}=\frac{\Gamma (n)d(n,p,q)}{2\pi ^{n}}\left(
|z||w|\right) ^{p+q}\left\vert \left\langle \frac{z}{|z|},\frac{w}{|w|} 
\right\rangle \right\vert ^{\left\vert p-q\right\vert }e^{i\left( p-q\right)
\arg \left( \left\langle \frac{z}{|z|},\frac{w}{|w|}\right\rangle \right) } 
\frac{P_{\min \left( p,q\right) }^{(n-2,\left\vert p-q\right\vert )}\left(
2\left\vert \left\langle \frac{z}{|z|},\frac{w}{|w|}\right\rangle
\right\vert ^{2}-1\right) }{P_{\min \left( p,q\right) }^{(n-2,\left\vert
p-q\right\vert )}(1)}.
\end{equation*}
Now, using the notation $R_{p,q}^{\gamma }(\xi )$ in \eqref{Zernike_poly}, $\mathfrak{S}_{n;p,q}^{z,w}$ also reads 
\begin{equation}  \label{Koor_sum}
\mathfrak{S}_{n;p,q}^{z,w}=(2\pi ^{n})^{-1}\Gamma
(n)d(n,p,q)(|z||w|)^{p+q}R_{p,q}^{n-2}\left( \left\langle \frac{z}{|z|}, 
\frac{w}{|w|}\right\rangle \right) .
\end{equation} 
On the other hand, we also need to write the terminating Gauss hypergeometric
functions $_{2}F{}_{1}$ in \eqref{Kern_2F1} in terms of Zernike
polynomials \eqref{Zernike_poly}. For that, we use \eqref{2F1-R} to obtain 
\begin{equation}  \label{2F1_Zern}
{}_{2}F{}_{1}\left( 
\begin{array}{c}
p-m,q-m-2\nu \\ 
n+p+q 
\end{array} 
\big|-|z|^{2}\right) =\left( 1+|z|^{2}\right) ^{m+\nu -\frac{p+q}{2} 
}R_{m-p,m-q+2\nu }^{n+p+q-1}\left( \left( 1+|z|^{2}\right) ^{-\frac{1}{2} 
}\right) .
\end{equation} 
Now, by replacing \eqref{Koor_sum} and \eqref{2F1_Zern} in \eqref{Kern_2F1},
the sum \eqref{repr_kern_1} takes the form 
\begin{equation}  \label{Kern2}
\begin{split}
K_{\nu ,m}(z,w)& =\sum_{p=0}^{m}\sum_{q=0}^{m+2\nu }\left[ (2\pi
^{n})^{-1}\Gamma (n)\left( \gamma _{p,q}^{n,\nu ,m}\right) ^{2}\right]
d(n,p,q)\left( \frac{\left( |z||w|\right) ^{2}}{\left( 1+|z|^{2}\right)
\left( 1+|w|^{2}\right) }\right) ^{\frac{1}{2}\left( p+q\right) } \\
& \times R_{m-p,m-q+2\nu }^{n+p+q-1}\left( \left( 1+|z|^{2}\right) ^{-\frac{1 
}{2}}\right) R_{m-p,m-q+2\nu }^{n+p+q-1}\left( \left( 1+|w|^{2}\right) ^{- 
\frac{1}{2}}\right) R_{p,q}^{n-2}\left( \left\langle \frac{z}{|z|},\frac{w}{ 
|w|}\right\rangle \right)
\end{split} 
\end{equation} 
with
\begin{equation}
(2\pi ^{n})^{-1}\Gamma (n)\left( \gamma _{p,q}^{n,\nu ,m}\right) ^{2}=\beta
_{\nu ,n,m}\frac{(-1)^{p+q}(-m)_{p}(-m-2\nu )_{q}(n+m+2\nu )_{p}(n+m)_{q}}{ 
(n)_{p+q}(n)_{p+q}},
\end{equation} 
where the constant
\begin{equation}
\beta _{\nu ,n,m}=\frac{(2m+2\nu +n)\Gamma (n+m)\Gamma (n+m+2\nu )}{\pi
^{n}\Gamma (n)m!(m+2\nu )!}
\end{equation} 
was obtained by using identities \eqref{binom} and \eqref{PochhammerGG}. Therefore, \eqref{Kern2} becomes
\begin{equation*}
\begin{split}
K_{\nu ,m}(z,w)& =\beta _{\nu ,n,m}\sum_{\substack{ 0\leq p\leq m  \\ 0\leq
q\leq m+2\nu }}\frac{(-1)^{p+q}(-m)_{p}(-m-2\nu )_{q}(n+m+2\nu )_{p}(n+m)_{q} 
}{(d(n,p,q))^{-1}(n)_{p+q}(n)_{p+q}}\left( \frac{|z|^{2}|w|^{2}}{ 
(1+|z|^{2})(1+|w|^{2})}\right) ^{\frac{p+q}{2}} \\
& \times R_{m-p,m-q+2\nu }^{n+p+q-1}\left( \left( 1+|z|^{2}\right) ^{-\frac{1 
}{2}}\right) R_{m-p,m-q+2\nu }^{n+p+q-1}\left( \left( 1+|w|^{2}\right) ^{- 
\frac{1}{2}}\right) R_{p,q}^{n-2}\left( \left\langle \frac{z}{|z|},\frac{w}{ 
|w|}\right\rangle \right) .
\end{split} 
\end{equation*} 
We now are in position to apply the addition formula for Zernike
polynomials due to \v{S}apiro \cite{Sapiro1968} and Koornwinder \cite 
{Koorn1972}: 
\begin{equation*}
\begin{split}
R_{k,l}^{\gamma }\left( z_{1}\bar{z}_{2}+(1-z_{1}\bar{z}_{1})^{\frac{1}{2} 
}(1-z_{2}\bar{z}_{2})^{\frac{1}{2}}y\right) &
=\sum_{p=0}^{k}\sum_{q=0}^{l}\tau_{p,q,\gamma -1}\frac{ 
(-1)^{p+q}(-k)_{p}(-l)_{q}(l+\gamma +1)_{p}(k+\gamma +1)_{q}}{(\gamma
+1)_{p+q}(\gamma +1)_{p+q}} \\
& \times \left[ (1-z_{1}\bar{z}_{1})(1-z_{2}\bar{z}_{2})\right] ^{\frac{p+q}{ 
2}}R_{k-p,l-q}^{\gamma +p+q}(z_{1})\overline{R_{k-p,l-q}^{\gamma +p+q}(z_{2}) 
}R_{p,q}^{\gamma -1}(y),
\end{split} 
\end{equation*} 
where 
\begin{equation}
\tau_{p,q,\gamma}:=\frac{(p+q+\gamma +1)(\gamma +1)_{p}(\gamma +1)_{q}}{ 
(\gamma +1)p!q!}.
\end{equation} 
Indeed, we specialize this formula for $z_{1}=\left( 1+|z|^{2}\right)^{- 
\frac{1}{2}}, \, z_2=\left( 1+|w|^{2}\right)^{-\frac{1}{2}},\ y=\left\langle 
\frac{z}{|z|},\frac{w}{|w|}\right\rangle ,\ k=m, \ l=m+2\nu $, and $\gamma
=n-1$ to obtain, after replacement, the expression
\begin{equation}\label{RK-R}
K_{\nu ,m}(z,w)=\beta _{\nu ,n,m}R_{m,m+2\nu }^{n-1}\left( \frac{1+\langle
z,w\rangle }{(1+|z|^{2})^{\frac{1}{2}}(1+|w|^{2})^{\frac{1}{2}}}\right) .
\end{equation} 
Using again \eqref{Zernike_poly}, equation \eqref{RK-R} can be rewritten as: 
\begin{equation}  \label{last_kern}
K_{\nu ,m}(z,w)=\frac{(2m+2\nu +n)\Gamma (m+2\nu +n)}{\pi ^{n}\Gamma (m+2\nu
+1)}\left( \frac{\left( 1+\langle w,z\rangle \right) ^{2}}{ 
(1+|z|^{2})(1+|w|^{2})}\right) ^{\nu }P_{m}^{(n-1,2\nu )}\left( \frac{ 
2|1+\langle z,w\rangle |^{2}}{(1+|z|^{2})(1+|w|^{2})}-1\right).
\end{equation} 
Recalling \eqref{d_FS}, we may also write \eqref{last_kern}
in the form \eqref{RK}. This ends the proof.

For $\nu =0$, the Fubini-Study Laplacian $\Delta _{0}\equiv\Delta _{FS}$ has a discrete spectral decomposition
with eigenvalues $\beta_m =(-4m(m+n))_{m\geq 0}$. Besides, each eigenspace is finite-dimensional and has a
orthonormal basis given by homogeneous spherical harmonics of degree zero. Setting $\nu =0$ in \eqref{rep_kern}, then the kernel of the orthogonal projection from $L^{2}(\mathbb{C}^{n},d\mu _{n})$ onto the $m$-th eigenspace of $\Delta_{0}$ reduces to
\begin{equation}
K_{0,m}(z,w)=\pi ^{-n}\left( 2m+n\right) \frac{(m+n-1)!}{m!} 
P_{m}^{(n-1,0)}(\cos 2d_{FS}(z,w)),  \label{psi_n}
\end{equation} 
in agreement with the result of Koornwinder \cite[Theorem 3.8]{Koo}.

For $\nu =0$, the spectral theorem implies that for any suitable function $U$, the operator $U(\Delta_{0})$ is an integral operator whose kernel is given by
\begin{equation}
\sum\limits_{m=0}^{+\infty }U(-4m(m+n))K_{0,m}(z,w).  \label{sum_w_psi}
\end{equation} 
In particular, one can write the kernel of the heat semigroup $\exp\left(t\Delta _{0}\right)$ through the series expansion 
\begin{equation}
H_{0}\left( t;z,w\right) =\pi ^{-n}\sum_{m\geq 0}\left( 2m+n\right) \frac{ 
(m+n-1)!}{m!}e^{-4m(m+n)t}P_{m}^{(n-1,0)}(\cos 2d_{FS}(z,w)),
\label{heat_kernel_nu=0}
\end{equation}
see \cite[p.873]{HI2002}.

Let $n\geq 1$, $2\nu \in\mathbb{Z}_+$ and $\rho =d_{FS}(z,w)$. Then, 
\begin{equation}\label{IRHK-AMH}
\begin{split}
H_{\nu }(t,z,w)&=\frac{e^{4t(\nu ^{2}+\frac{n^{2}}{4})}}{2^{n+2\nu -1}\pi
^{n}\Gamma \left( 2\nu +\frac{1}{2}\right) }\left( \frac{(1+\langle
z,z\rangle )(1+\langle w,w\rangle )}{(1+\langle z,w\rangle )^{2}}\right)
^{\nu }\\
&\times \int_{\rho }^{\frac{\pi }{2}}\frac{-d(\cos u)}{\left( \cos ^{2}\rho
-\cos ^{2}u\right) ^{\frac{1}{2}-2\nu }}\left( -\frac{1}{\sin u}\frac{d}{du} 
\right) ^{n+2\nu }\left[ \Theta _{n+1,\nu }(t,u)\right] 
\end{split}
\end{equation}
where 
\begin{equation*}
\Theta _{n+1,\nu }(t,u):=\sum_{m=0}^{\infty }e^{-4t(m+\nu +\frac{n}{2} 
)^{2}}\cos (2m+2\nu +n)u.
\end{equation*}

We first write the heat kernel in terms of the reproducing kernel \eqref{RK} as follows 
\begin{equation}\label{HK=sum(expK)}
\begin{split}
\quad H_{\nu }(t,z,w)&=\sum\limits_{m=0}^{+\infty }e^{\beta_{m}t}K_{\nu,m}(z,w)\\
&=\sum\limits_{m=0}^{+\infty }e^{\beta_{m}t}\frac{(2m+2\nu +n)\Gamma (m+2\nu +n)}{\pi^{n}\Gamma (m+2\nu +1)}\left( \frac{\left( 1+\langle w,z\rangle \right) ^{2}}{(1+|z|^{2})(1+|w|^{2})}\right) ^{\nu } \\
 & \qquad\qquad\qquad\times P_{m}^{(n-1,2\nu )}\left( \frac{2|1+\langle z,w\rangle |^{2}}{(1+|z|^{2})(1+|w|^{2})}-1\right) .
\end{split}
\end{equation} 
Next, we will use the integral representation for Jacobi polynomials in terms of Gegenbauer polynomials given in \cite[p.194]{DK1971} followed by the symmetry relation $P_{k}^{(\alpha ,\beta
)}(-x)=(-1)^{k}P_{k}^{(\beta ,\alpha )}(x)$, 
\begin{equation}\label{IR_Jac-Geg}
P_{k}^{(\alpha ,\beta )}(2t^{2}-1)=\frac{2\Gamma (\alpha +\beta +1)\Gamma
(k+\beta +1)}{\Gamma (\beta +\frac{1}{2})\Gamma (k+\alpha +\beta +1)} 
\int_{0}^{1}(1-u^{2})^{\beta -\frac{1}{2}}C_{2k}^{\alpha +\beta +1}(tu)du,
\end{equation} 
$Re\alpha >-\frac{1}{2},\ Re\beta >-\frac{1}{2}$ and $|t|<1$. Precisely, we set $t=\cos \rho $ and $u=\cos \psi /\cos \rho $, then we specialize $\alpha =n-1,\ \beta =2\nu$ and $ k=m$ in \eqref{IR_Jac-Geg} to get that 
\begin{equation}
P_{m}^{(n-1 ,2\nu )}(\cos 2\rho)=\frac{2\Gamma (n+2\nu )\Gamma (m+2\nu
+1)}{\Gamma (2\nu +\frac{1}{2})\Gamma (m+2\nu +n)}\frac{1}{\cos ^{4\nu }\rho}
\int_{\rho}^{\frac{\pi }{2}}\frac{\sin \psi }{\left( \cos ^{2}\rho-\cos
^{2}\psi \right) ^{\frac{1}{2}-2\nu }}C_{2m}^{n+2\nu }(\cos \psi
)d\psi .
\end{equation} 
By substituting the above representation in \eqref{HK=sum(expK)}, we obtain, after some calculations, the following
\begin{equation}  \label{Q_int}
\begin{split}
H_{\nu }(t,z,w)& =\frac{2\Gamma (n+2\nu )e^{4t(\nu^2+\frac{n^2}{4})} 
}{\Gamma (2\nu +\frac{1}{2})\cos ^{4\nu }\rho}D_{\nu }(z,w) \\
& \times \int_{\rho}^{\frac{\pi }{2}}\frac{\sin \psi }{\left( \cos
^{2}\theta -\cos ^{2}\psi \right) ^{\frac{1}{2}-2\nu }}\left(
\sum\limits_{m=0}^{+\infty }(2m+2\nu +n)C_{2m}^{n+2\nu }(\cos \psi
)e^{-4t(m+\nu +\frac{n}{2})^2}\right) d\psi ,
\end{split} 
\end{equation}
where 
\begin{equation*}
D_{\nu }(z,w):=\left(\frac{(1+\langle w,z\rangle )^2\cos^{-4}\rho}{(1+|z|^{2})(1+|w|^{2})} \right)^{\nu }.
\end{equation*}
Next, we use the formula \cite[p.876]{HI2002}: 
\begin{equation}
\left( -\frac{d}{\sin udu}\right) ^{l}\left( \frac{\sin (k+l+1)u}{\sin u} 
\right) =2^{l}l!C_{k}^{l+1}(\cos u),
\end{equation} 
for $l=n+2\nu ,\ k=2m,\ u=\psi $ to rewrite the series occurring in \eqref{Q_int} as 
\begin{equation}  \label{der_sum}
\frac{2^{1-n-2\nu }}{(n+2\nu -1)!}\left( -\frac{d}{\sin \psi d\psi } 
\right) ^{n-1+2\nu }\left( \sum\limits_{m=0}^{+\infty }\frac{(2m+2\nu
+n)\sin (2m+2\nu +n)\psi }{\sin \psi }e^{-4t(m+\nu +\frac{n}{2})^2}\right) .
\end{equation}
But since 
\begin{equation}
\frac{(2m+2\nu +n)\sin (2m+2\nu +n)\psi }{\sin \psi }=-\frac{d}{\sin
\psi d\psi }(\cos (2m+2\nu +n)\psi ).
\end{equation}
Equation \eqref{der_sum} may be presented as 
\begin{equation}  \label{der_theta}
\frac{2^{1-n-2\nu }}{(n+2\nu -1)!}\left( -\frac{d}{\sin \psi d\psi } 
\right) ^{n+2\nu }\left[ \Theta _{n+1,\nu }(t,\psi )\right]
\end{equation}
where 
\begin{equation}
\Theta _{n+1,\nu }(t,\psi )=\sum\limits_{m=0}^{+\infty}e^{-4t(m+\nu +\frac{n}{2})^2}\cos (2m+2\nu+n)\psi.
\end{equation}
Finally, by substituting \eqref{der_theta} into \eqref{Q_int} we arrive at the announced result \eqref{IRHK-AMH}.

The heat trace formula \eqref{HTF} satisfies the asymptotic expansion
\begin{equation}
Tr\left( \exp\left(\frac{1}{4}t\Delta _{\nu }\right)\right) \simeq \frac{1}{(4\pi t)^{n}} 
\sum\limits_{j=0}^{+\infty }b_{j}^{\left( \nu ,n\right) }\ t^{j},\text{ \  \ 
}t\searrow 0^{+} 
\end{equation}
with the heat coefficients given by
\begin{equation*}
b_{j}^{\left( \nu ,n\right) }=\frac{(4\pi)^n}{n!}
\sum\limits_{i=0}^{j}\frac{\left( \frac{n^{2}}{4}+\nu ^{2}\right) ^{j-i}}{\left( j-i\right) !}c_{i}^{\left( \nu ,n\right) },\text{ \ }
\end{equation*}
\begin{itemize}
\item[(i)] case $n$ odd
\begin{equation}
c_{i}^{\left( \nu ,n\right) }=\left\{ 
\begin{array}{c}
\frac{(n-i-1)!}{(n-1)!}\gamma _{n-i-1}^{(\nu ,n)},\quad\qquad\qquad\qquad\qquad 0\leq i\leq n-1 \\ 
\sum\limits_{p=0}^{n-1}\frac{(-1)^{i-n+1}c_{p}^{\left( \nu ,n\right)}}{(i-n)!(i-p)p!} B_{2(i-p)}\left(\nu+\frac{1}{2}\right)
,\quad i\geq n 
\end{array} 
\right.   
\end{equation}

\item[(ii)] case $n$ even
\begin{eqnarray}
\begin{split}
c_{i}^{\left( \nu ,n\right) }=\left\{
\begin{array}{c}
1,\qquad\qquad\qquad\qquad\qquad\qquad\qquad i=0\\
\tau _{n-1-i}^{(\nu ,n)}\frac{\left(n-i-1\right) !}{\left( n-1\right) !},\qquad\qquad\qquad\qquad\qquad 1\leq i\leq n-1\\
\sum\limits_{p=0}^{n-1}\frac{(-1)^{i-n}c_{p}^{\left( \nu ,n\right)}}{(i-n)!(i-p)(n-p-1)!}\left[ 2B_{2(i-p)}-B_{2(i-p)}(\nu)\right] ,\qquad i\geq n
\end{array}
\right.
\end{split}
\end{eqnarray}
\end{itemize} 
where $B_d$ and $B_d(\cdot)$ denote Bernoulli numbers and polynomials respectively (see Appendix \ref{appendix1}). The coefficients $\tau _{i}^{(\nu ,n)}$ and $\gamma_{i}^{(\nu ,n)}$ are defined by \eqref{dim_sum_1} and \eqref{dim_A_case2} respectively.

We may rewrite \eqref{dim_A_m_nu} as
\begin{equation}\label{dim_A_prod}
\dim _{\mathbb{C}}\mathcal{A}_{m}^{\nu }=\frac{2m+n+2\nu }{n!(n-1)!} 
\prod\limits_{j=1}^{n-1}(m+j)(m+2\nu +j) .
\end{equation}
Setting $r=r\left( m\right) =m+\nu +\frac{n}{2}$, the product in \eqref{dim_A_prod} also reads
\begin{equation}\label{wp}
\mathcal{\wp }=\prod\limits_{j=1}^{n-1}\left( r-\frac{n}{2}-\nu +j\right) \left( r-\frac{n}{ 
2}+\nu +j\right) .
\end{equation} 
We treat the cases of $n$ odd and $n$ even separately as
they correspond to different choices of theta functions.\\

$\left( i\right) $\textbf{\ \textit{Case odd} $n\geq 0$.}  The product \eqref{wp} can also be presented as 
\begin{equation}\label{dim_prod_2}
\mathcal{\wp }=\prod\limits_{l=\frac{1}{2}+\nu }^{\frac{n}{2}+\nu -1}\left(
r^{2}-l^{2}\right) \prod\limits_{s=\frac{1}{2}-\nu }^{\frac{n}{2}-\nu
-1}\left( r^{2}-s^{2}\right) 
\end{equation} 
and further it can be decomposed as 
\begin{equation}\label{dim_sum_1}
\mathcal{\wp }=\sum\limits_{p=0}^{n-1}\gamma _{p}^{(\nu ,n)}r^{2p}. 
\end{equation} 
where the numbers $\gamma _{0}^{(\nu ,n)},...,\gamma _{n-1}^{(\nu ,n)}$ can
be computed explicitly (see Sect.\ref{Sect8}). By using \eqref{dim_sum_1},
the multiplicity in \eqref{dim_A_prod} takes the form

\begin{equation}\label{dim_A_sum_2}
\dim _{\mathbb{C}}\mathcal{A}_{m}^{\nu }=\frac{2}{n!(n-1)!} 
\sum\limits_{p=0}^{n-1}\gamma _{p}^{(\nu ,n)}\left( m+\nu +\frac{n}{2} 
\right) ^{2p+1}
\end{equation} 
which we may use to rewrite the trace formula \eqref{HTF} as
\begin{eqnarray}
\begin{split}
Tr\left( e^{\frac{1}{4}t\Delta _{\nu }}\right) &=e^{\left( \frac{n^{2} 
}{4}+\nu ^{2}\right) t}\sum\limits_{m=0}^{+\infty }\left[ \frac{2}{n!(n-1)!} 
\sum\limits_{p=0}^{n-1}\gamma _{p}^{(\nu ,n)}\left( m+\nu +\frac{n}{2} 
\right) ^{2p+1}\right] e^{-\left( m+\frac{n}{2}+\nu \right) ^{2}t} \\
&=\frac{e^{\left( \frac{n^{2}}{4}+\nu ^{2}\right) t}}{n!(n-1)!}\mathcal{S} 
\end{split}
\end{eqnarray}
with 
\begin{equation}
\mathcal{S}:=\sum\limits_{p=0}^{n-1}\gamma _{p}^{(\nu ,n)}\left(
2\sum\limits_{m=0}^{+\infty }\left( m+\nu +\frac{n}{2}\right)
^{2p+1}e^{-\left( m+\frac{n}{2}+\nu \right) ^{2}t}\right) .  
\end{equation} 
The latter sum can be cast into two parts as 
\begin{equation}\label{dim_double_sum}
\mathcal{S}=2\sum\limits_{\mu =\nu +\frac{1}{2}}^{+\infty }\mu e^{-\mu
^{2}t}\sum\limits_{p=0}^{n-1}\gamma _{p}^{(\nu ,n)}\mu
^{2p}-2\sum\limits_{\mu =\nu +\frac{1}{2}}^{\nu +\frac{n}{2}-1}\mu e^{-\mu
^{2}t}\sum\limits_{p=0}^{n-1}\gamma _{p}^{(\nu ,n)}\mu ^{2p}  
\end{equation} 
Recalling \eqref{dim_prod_2}-\eqref{dim_sum_1}, we see that for $\mu $ raining over the set $\{\nu +\frac{1}{2},\nu +\frac{3}{2},\cdots ,\nu +\frac{n}{2}-1\}$ the sum 
\begin{equation}
\sum\limits_{p=0}^{n-1}\gamma _{p}^{(\nu ,n)}\mu ^{2p}=0
\end{equation}
and therefore the sum \eqref{dim_double_sum} reduces to 
\begin{equation}\label{sum_S_R}
\mathcal{S}=2\sum\limits_{p=0}^{n-1}\gamma _{p}^{(\nu ,n)}\mathcal{R} 
_{p}^{\left( \nu \right) }\left( t\right) 
\end{equation}
where 
\begin{equation}
