\frac{1}{2}}^{+\infty }\mu ^{2p+1}e^{-\mu ^{2}t} 
\end{equation} 
By setting $\mu =j+\frac{1}{2},$ we successively obtain
\begin{eqnarray}
\mathcal{R}_{p}^{\left( \nu \right) }\left( t\right) &=&\sum\limits_{j=\nu
}^{+\infty }\left( j+\frac{1}{2}\right) ^{2p+1}e^{-\left( j+\frac{1}{2} 
\right) ^{2}t} \nonumber \\
&=&\sum\limits_{j=0}^{+\infty }\left( j+\frac{1}{2}\right) ^{2p+1}e^{-\left( j+ 
\frac{1}{2}\right) ^{2}t}-\sum\limits_{j=0}^{\nu -1}\left( j+\frac{1}{2} 
\right) ^{2p+1}e^{-\left( j+\frac{1}{2}\right) ^{2}t} \nonumber \\
&=&\frac{1}{2}\left( -\frac{d}{dt}\right) ^{p}\left[ \sum\limits_{j=0}^{+ 
\infty }\left( 2j+1\right) e^{-\left( j+\frac{1}{2}\right) ^{2}t}\right]
-\sum\limits_{j=0}^{\nu -1}\left( j+\frac{1}{2}\right) ^{2p+1}e^{-\left( j+ 
\frac{1}{2}\right) ^{2}t} \nonumber\\
&=&\frac{1}{2}\left( -\frac{d}{dt}\right) ^{p}\left[ \vartheta _{2}(t)\right]
-\sum\limits_{j=0}^{\nu -1}\left( j+\frac{1}{2}\right) ^{2p+1}e^{-\left( j+ 
\frac{1}{2}\right) ^{2}t} \label{finite_sum}
\end{eqnarray}
where $\vartheta _{2}(t)$ denotes the Jacobi's theta function given by \cite[p.280]{M_1928}: 
\begin{equation}
\vartheta _{2}(t)=\sum\limits_{j=0}^{+\infty }\left( 2j+1\right) e^{-\left(
j+\frac{1}{2}\right) ^{2}t}  
\end{equation} 
while the finite sum in \eqref{finite_sum} may be expressed by the series 
\begin{equation}
\sum\limits_{\ell =0}^{+\infty }\sigma _{p}^{(\nu )}\left( \ell \right) \
t^{\ell }  
\end{equation} 
with coefficients 
\begin{equation}
\sigma _{p}^{\left( \nu \right) }\left( \ell \right) =\frac{(-1)\ell }{\ell ! 
}\sum\limits_{j=0}^{\nu -1}\left( j+\frac{1}{2}\right) ^{2(p+\ell )+1}. 
\end{equation} 
Now, we use the formula \cite[p.597]{prud1}:
\begin{equation}
\sum\limits_{k=0}^{m}(k+a)^q=\frac{1}{q+1}\left[ B_{q+1}(m+1+a)-B_{q+1}(a)\right], \quad q=1,2,\cdots ,
\end{equation}
where $B_n(z)$ are the Bernoulli polynomials, for $m=\nu-1$, $q=2(\ell+p)+1$, $a=\frac{1}{2}$, to get 
\begin{equation}
\sigma _{p}^{\left( \nu \right) }\left( \ell \right) =\frac{(-1)^{\ell}}{2(p+\ell +1)\ell !}\left[ B_{2(p+\ell +1)}\left(\nu+\frac{1}{2}\right)-B_{2(p+\ell +1)}\left(\frac{1}{2}\right)\right]. 
