\end{split}
\end{eqnarray}
Therefore, we may rewrite \eqref{trace_exp-sum} as 
\begin{equation}\label{trace_prod_2}
Tr\left( e^{\frac{1}{4}t\Delta _{\nu }}\right) \simeq \frac{\omega _{n}}{ 
(4\pi t)^{n}}\left[ \sum\limits_{k=0}^{+\infty }c_{k}^{\left( \nu ,n\right)
}\ t^{k}\right] \left[ \sum\limits_{j=0}^{+\infty }\frac{1}{j!}\left( \frac{ 
n^{2}}{4}+\nu ^{2}\right) ^{j}\right] .
\end{equation} 
Finally, in both cases the r.h.s of \eqref{trace_prod_1} and \eqref{trace_prod_2} may also be seen as a Cauchy product of two power series as   
\begin{equation*}
Tr\left( e^{\frac{1}{4}t\Delta _{\nu }}\right) \simeq\frac{1}{(4\pi t)^{n}} 
\sum\limits_{d=0}^{+\infty }\left[ \omega _{n}\sum\limits_{i=0}^{d}\frac{ 
\left( n^{2}+4\nu ^{2}\right) ^{d-i}}{4^{d-i}\left( d-i\right) !} 
c_{i}^{\left( \nu ,n\right) }\right] t^{d}.
\end{equation*}
This ends the proof of the theorem.
